/* Linear — dark, dense, engineered calm. Palette derived from awesome-design-md (MIT). */
@theme {
	--color-primary: #5e6ad2;
	--color-primary-foreground: #ffffff;
	--color-surface: #08090a;
	--color-surface-foreground: #f7f8f8;
	--color-surface-raised: #131416;
	--color-muted: #8a8f98;
	--color-accent: #26b5ce;
	--color-danger: #eb5757;
	--color-border: #26282d;

	--radius-sm: 4px;
	--radius-md: 6px;
	--radius-lg: 8px;
	--radius-xl: 12px;
	--radius-2xl: 16px;

	--shadow-sm: 0 1px 2px rgb(0 0 0 / 0.5);
	--shadow-md: 0 4px 16px rgb(0 0 0 / 0.5);
	--shadow-lg: 0 16px 48px rgb(0 0 0 / 0.6);
}

